// Rebuild the title as "Page ‹ Site name" (translation-independent).
function perfectpixel_clean_admin_title( $full_title, $title ) {
	$site  = wp_strip_all_tags( get_bloginfo( 'name', 'display' ) );
	$title = trim( wp_strip_all_tags( (string) $title ) );
	if ( '' === $site ) {
		return '' !== $title ? $title : $full_title;
	}
	return '' !== $title ? $title . ' &lsaquo; ' . $site : $site;
}
